#include <iostream>
#include <vector>
#include <queue>
#include <cstring>
#include <algorithm>
#include <array>
using namespace std;

const int MAXN = 300;
const int INF = 1000000000;

struct Edge {
    int to, rev, flow, capacity;
    Edge(int t, int r, int f, int c) : to(t), rev(r), flow(f), capacity(c) {}
};

vector<Edge> graph[MAXN];
int dist[MAXN], current_ptr[MAXN], source, sink;

void add_edge(int u, int v, int cap, int rcap = 0) {
    graph[u].emplace_back(v, graph[v].size(), 0, cap);
    graph[v].emplace_back(u, graph[u].size() - 1, 0, rcap);
}

bool bfs() {
    memset(dist, -1, sizeof(dist));
    dist[source] = 0;
    queue<int> q;
    q.push(source);
    while (!q.empty() && dist[sink] == -1) {
        int u = q.front(); q.pop();
        for (const auto& e : graph[u]) {
            int v = e.to;
            if (dist[v] == -1 && e.flow < e.capacity) {
                dist[v] = dist[u] + 1;
                q.push(v);
            }
        }
    }
    return dist[sink] != -1;
}

int dfs(int u, int flow_limit) {
    if (u == sink || !flow_limit) return flow_limit;
    for (int& i = current_ptr[u]; i < (int)graph[u].size(); ++i) {
        Edge& e = graph[u][i];
        int v = e.to;
        if (dist[v] != dist[u] + 1) continue;
        int pushed = dfs(v, min(flow_limit, e.capacity - e.flow));
        if (pushed) {
            e.flow += pushed;
            graph[v][e.rev].flow -= pushed;
            return pushed;
        }
    }
    return 0;
}

int max_flow() {
    int total = 0;
    while (bfs()) {
        memset(current_ptr, 0, sizeof(current_ptr));
        int pushed;
        while ((pushed = dfs(source, INF))) {
            total += pushed;
        }
    }
    return total;
}

const int dx[4] = {-1, 0, 0, 1};
const int dy[4] = {0, -1, 1, 0};

int rows, max_dist;
vector<vector<int>> blocked, time_limit, distances;
vector<string> original, required;

void bfs_grid(int start_r, int start_c, vector<vector<int>>& dist_grid, bool use_time_limit = false) {
    for (int i = 0; i < rows; ++i)
        fill(dist_grid[i].begin(), dist_grid[i].end(), -1);
    dist_grid[start_r][start_c] = 0;
    queue<array<int, 2>> q;
    q.push({start_r, start_c});
    while (!q.empty()) {
        auto [r, c] = q.front(); q.pop();
        if (use_time_limit && dist_grid[r][c] == time_limit[r][c]) continue;
        for (int d = 0; d < 4; ++d) {
            int nr = r + dx[d], nc = c + dy[d];
            if (nr < 0 || nr >= rows || nc < 0 || nc >= rows || dist_grid[nr][nc] != -1 || blocked[nr][nc]) continue;
            if (use_time_limit && time_limit[nr][nc] > -1 && dist_grid[r][c] + 1 > time_limit[nr][nc]) continue;
            dist_grid[nr][nc] = dist_grid[r][c] + 1;
            q.push({nr, nc});
        }
    }
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    cin >> rows >> max_dist;
    original.resize(rows);
    required.resize(rows);
    for (auto& s : original) cin >> s;
    for (auto& s : required) cin >> s;
    blocked.assign(rows, vector<int>(rows));
    time_limit.assign(rows, vector<int>(rows));
    distances.assign(rows, vector<int>(rows));
    for (int i = 0; i < rows; ++i)
        for (int j = 0; j < rows; ++j)
            blocked[i][j] = (original[i][j] == 'Y');
    for (int i = 0; i < rows; ++i)
        for (int j = 0; j < rows; ++j)
            if (original[i][j] == 'Z')
                bfs_grid(i, j, time_limit);
    source = 2 * rows * rows + 5;
    sink = source + 1;
    for (int x = 0; x < rows; ++x) {
        for (int y = 0; y < rows; ++y) {
            if (original[x][y] == 'Z' || original[x][y] == 'Y') continue;
            add_edge(source, rows * x + y, original[x][y] - '0');
            add_edge(rows * rows + rows * x + y, sink, required[x][y] - '0');
            bfs_grid(x, y, distances, true);
            for (int xp = 0; xp < rows; ++xp) {
                for (int yp = 0; yp < rows; ++yp) {
                    if (distances[xp][yp] != -1 && distances[xp][yp] <= max_dist) {
                        add_edge(rows * x + y, rows * rows + rows * xp + yp, INF);
                    }
                }
            }
        }
    }
    cout << max_flow() << '\n';
    return 0;
}
